\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SHOW transaction_read_only;
SELECT current_database()='tcdx-grc' AND current_user='postgres'
 AND inet_server_addr()='192.168.2.40'::inet AND inet_server_port()=5432
 AND current_setting('server_version_num')::integer/10000=16
 AND current_setting('transaction_read_only')='on'
 AND current_setting('default_transaction_read_only')='on'
 AND current_setting('statement_timeout')='5s' AND current_setting('lock_timeout')='1s'
 AND NOT pg_is_in_recovery() AS qa_identity_ok \gset
\if :qa_identity_ok
SELECT jsonb_build_object('category','identity','database',current_database(),
 'user',current_user,'server_address',inet_server_addr(),'server_port',inet_server_port(),
 'version',version(),'server_version_num',current_setting('server_version_num'),
 'default_transaction_read_only',current_setting('default_transaction_read_only'),
 'transaction_read_only',current_setting('transaction_read_only'),
 'statement_timeout',current_setting('statement_timeout'),'lock_timeout',current_setting('lock_timeout'),
 'cluster_name',current_setting('cluster_name',true),'in_recovery',pg_is_in_recovery(),
 'role_superuser',(SELECT rolsuper FROM pg_catalog.pg_roles WHERE rolname=current_user));
SELECT jsonb_build_object('category','extensions','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT extname,extversion FROM pg_catalog.pg_extension ORDER BY extname LIMIT 50) x;
SELECT jsonb_build_object('category','namespaces','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT nspname,pg_get_userbyid(nspowner) AS owner FROM pg_catalog.pg_namespace WHERE nspname IN ('knowledge','config','regulatory','controls','org','ops_audit','iam','platform') ORDER BY nspname LIMIT 20) x;
SELECT jsonb_build_object('category','relations','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||c.relname AS name,c.relkind,pg_get_userbyid(c.relowner) AS owner,c.reltuples::bigint AS estimated_rows,c.relrowsecurity,c.relforcerowsecurity FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname||'.'||c.relname=ANY(ARRAY['knowledge.knowledge_sources','knowledge.knowledge_items','knowledge.knowledge_versions','knowledge.knowledge_version_context_links','knowledge.knowledge_source_usage_rights','regulatory.normative_units','regulatory.requirements','regulatory.requirement_applicabilities','regulatory.regulatory_pack_versions','controls.control_versions','org.subjects','config.configuration_definitions','config.configuration_overrides','config.effective_configurations','config.configuration_definition_scopes','config.configuration_validation_rules','config.effective_configuration_layers','ops_audit.audit_events','ops_audit.lifecycle_transition_definitions','iam.permissions','iam.role_permissions','platform.schema_migrations']) ORDER BY name LIMIT 100) x;
SELECT jsonb_build_object('category','columns','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||c.relname AS relation,a.attname AS name,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull,pg_get_expr(d.adbin,d.adrelid) AS default_expression,a.attidentity,a.attgenerated FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname||'.'||c.relname=ANY(ARRAY['knowledge.knowledge_sources','knowledge.knowledge_items','knowledge.knowledge_versions','knowledge.knowledge_version_context_links','knowledge.knowledge_source_usage_rights','regulatory.normative_units','regulatory.requirements','regulatory.requirement_applicabilities','regulatory.regulatory_pack_versions','controls.control_versions','org.subjects','config.configuration_definitions','config.configuration_overrides','config.effective_configurations','config.configuration_definition_scopes','config.configuration_validation_rules','config.effective_configuration_layers','ops_audit.audit_events','ops_audit.lifecycle_transition_definitions','iam.permissions','iam.role_permissions','platform.schema_migrations']) AND a.attnum>0 AND NOT a.attisdropped ORDER BY relation,a.attnum LIMIT 1500) x;
SELECT jsonb_build_object('category','constraints','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||c.relname AS relation,k.conname AS name,k.contype,k.convalidated,k.condeferrable,k.condeferred,pg_get_constraintdef(k.oid,true) AS definition FROM pg_catalog.pg_constraint k JOIN pg_catalog.pg_class c ON c.oid=k.conrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname||'.'||c.relname=ANY(ARRAY['knowledge.knowledge_sources','knowledge.knowledge_items','knowledge.knowledge_versions','knowledge.knowledge_version_context_links','knowledge.knowledge_source_usage_rights','regulatory.normative_units','regulatory.requirements','regulatory.requirement_applicabilities','regulatory.regulatory_pack_versions','controls.control_versions','org.subjects','config.configuration_definitions','config.configuration_overrides','config.effective_configurations','config.configuration_definition_scopes','config.configuration_validation_rules','config.effective_configuration_layers','ops_audit.audit_events','ops_audit.lifecycle_transition_definitions','iam.permissions','iam.role_permissions','platform.schema_migrations']) ORDER BY relation,name LIMIT 2000) x;
SELECT jsonb_build_object('category','indexes','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||c.relname AS relation,i.relname AS name,x.indisvalid,x.indisready,pg_get_indexdef(i.oid) AS definition FROM pg_catalog.pg_index x JOIN pg_catalog.pg_class c ON c.oid=x.indrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_class i ON i.oid=x.indexrelid WHERE n.nspname||'.'||c.relname=ANY(ARRAY['knowledge.knowledge_sources','knowledge.knowledge_items','knowledge.knowledge_versions','knowledge.knowledge_version_context_links','knowledge.knowledge_source_usage_rights','regulatory.normative_units','regulatory.requirements','regulatory.requirement_applicabilities','regulatory.regulatory_pack_versions','controls.control_versions','org.subjects','config.configuration_definitions','config.configuration_overrides','config.effective_configurations','config.configuration_definition_scopes','config.configuration_validation_rules','config.effective_configuration_layers','ops_audit.audit_events','ops_audit.lifecycle_transition_definitions','iam.permissions','iam.role_permissions','platform.schema_migrations']) ORDER BY relation,name LIMIT 2000) x;
SELECT jsonb_build_object('category','functions','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||p.proname AS name,pg_get_function_identity_arguments(p.oid) AS arguments,p.prosecdef,pg_get_userbyid(p.proowner) AS owner,pg_get_functiondef(p.oid) AS definition FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=ANY(ARRAY['knowledge.check_context_link','knowledge.guard_context_link','knowledge.guard_context_target_owner','knowledge.guard_published_version_core','knowledge.enforce_source_usage_rights','config.guard_control_override_history','config.check_control_override_successor','regulatory.guard_context_decision_history']) AND p.prokind='f' ORDER BY name LIMIT 30) x;
SELECT jsonb_build_object('category','triggers','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||c.relname AS relation,t.tgname AS name,t.tgenabled,pg_get_triggerdef(t.oid,true) AS definition FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname||'.'||c.relname=ANY(ARRAY['knowledge.knowledge_sources','knowledge.knowledge_items','knowledge.knowledge_versions','knowledge.knowledge_version_context_links','knowledge.knowledge_source_usage_rights','regulatory.normative_units','regulatory.requirements','regulatory.requirement_applicabilities','regulatory.regulatory_pack_versions','controls.control_versions','org.subjects','config.configuration_definitions','config.configuration_overrides','config.effective_configurations','config.configuration_definition_scopes','config.configuration_validation_rules','config.effective_configuration_layers','ops_audit.audit_events','ops_audit.lifecycle_transition_definitions','iam.permissions','iam.role_permissions','platform.schema_migrations']) AND NOT t.tgisinternal ORDER BY relation,name LIMIT 200) x;
SELECT jsonb_build_object('category','sequences','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT schemaname,sequencename,data_type,increment_by,cycle FROM pg_catalog.pg_sequences WHERE schemaname IN ('knowledge','config','regulatory','controls','org','ops_audit') ORDER BY schemaname,sequencename LIMIT 100) x;
SELECT jsonb_build_object('category','dependencies','rows',coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)) FROM (SELECT n.nspname||'.'||c.relname AS relation,d.deptype,d.classid::regclass::text AS class,d.refclassid::regclass::text AS referenced_class,pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid) AS referenced_object FROM pg_catalog.pg_depend d JOIN pg_catalog.pg_class c ON d.classid='pg_class'::regclass AND c.oid=d.objid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname||'.'||c.relname=ANY(ARRAY['knowledge.knowledge_sources','knowledge.knowledge_items','knowledge.knowledge_versions','knowledge.knowledge_version_context_links','knowledge.knowledge_source_usage_rights','regulatory.normative_units','regulatory.requirements','regulatory.requirement_applicabilities','regulatory.regulatory_pack_versions','controls.control_versions','org.subjects','config.configuration_definitions','config.configuration_overrides','config.effective_configurations','config.configuration_definition_scopes','config.configuration_validation_rules','config.effective_configuration_layers','ops_audit.audit_events','ops_audit.lifecycle_transition_definitions','iam.permissions','iam.role_permissions','platform.schema_migrations']) ORDER BY relation,d.deptype LIMIT 1000) x;
\else
\quit 3
\endif
ROLLBACK;
